const lockSessionQueue = `-- name: LockSessionQueue :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::text, 0))
`

// Serializes writers of one session queue for the length of the transaction, so
// the capacity count and the insert that follows it see the same queue.
func (q *Queries) LockSessionQueue(ctx context.Context, lockKey string) error {
	_, err := q.db.Exec(ctx, lockSessionQueue, lockKey)
	return err
}

